result.statement:
∀ n : ℕ, 0 < n →
  let N : ℕ := n;
  let stdBoard : Fin N × Fin N → ZMod 2 := fun p => ((p.1.val + p.2.val : ℕ) : ZMod 2);
  let swapRows : (i j : Fin N) → (Fin N × Fin N → ZMod 2) → (Fin N × Fin N → ZMod 2) :=
    fun i j b p => b (if p.1 = i then j else if p.1 = j then i else p.1, p.2);
  let swapCols : (i j : Fin N) → (Fin N × Fin N → ZMod 2) → (Fin N × Fin N → ZMod 2) :=
    fun i j b p => b (p.1, if p.2 = i then j else if p.2 = j then i else p.2);
  let applyOp : ((Fin N × Fin N) ⊕ (Fin N × Fin N)) → (Fin N × Fin N → ZMod 2) → (Fin N × Fin N → ZMod 2) :=
    fun op b => match op with
      | Sum.inl (i, j) => swapRows i j b
      | Sum.inr (i, j) => swapCols i j b;
  let applyOps : List ((Fin N × Fin N) ⊕ (Fin N × Fin N)) → (Fin N × Fin N → ZMod 2) → (Fin N × Fin N → ZMod 2) :=
    fun ops b => ops.foldl (fun b op => applyOp op b) b;
  let A : ℕ := if Even N then N / 2 else N - 1;
  (∀ (b : Fin N × Fin N → ZMod 2),
      (∃ ops : List ((Fin N × Fin N) ⊕ (Fin N × Fin N)),
        b = applyOps ops (stdBoard)) →
      ∃ ops : List ((Fin N × Fin N) ⊕ (Fin N × Fin N)),
        applyOps ops b = stdBoard ∧ ops.length ≤ A) ∧
  (∃ (b : Fin N × Fin N → ZMod 2),
      (∃ ops : List ((Fin N × Fin N) ⊕ (Fin N × Fin N)),
        b = applyOps ops (stdBoard)) ∧
      (∃ ops : List ((Fin N × Fin N) ⊕ (Fin N × Fin N)),
        applyOps ops b = stdBoard) ∧
      (∀ ops : List ((Fin N × Fin N) ⊕ (Fin N × Fin N)),
        applyOps ops b = stdBoard → A ≤ ops.length))
